// Generated by tack build. Do not edit. Forwards to the daemon; fails closed.
const net = require("node:net");
const fs = require("node:fs");
const path = require("node:path");
const os = require("node:os");
const { spawn } = require("node:child_process");

const MANIFEST = __TACK_MANIFEST__;
const DAEMON_BIN = __TACK_DAEMON_BIN__;
const PLUGIN_DIR = __TACK_PLUGIN_DIR__;
const DENY_REASONS = __TACK_DENY_REASONS__;
const CALL_TIMEOUT_MS = __TACK_CALL_TIMEOUT_MS__;
const START_TIMEOUT_MS = __TACK_START_TIMEOUT_MS__;
const PROTOCOL_VERSION = __TACK_PROTOCOL_VERSION__;

const KINDS = new Set(["hook", "tool", "error"]);
const MAX_LINE = 1024 * 1024;
const POLL_MS = 25;

// State folder shared with the daemon: an explicit TACK_STATE_DIR is used
// as-is; XDG_STATE_HOME is suffixed with "tack"; the home fallback is
// ".local/state/tack".
let state;
if (process.env.TACK_STATE_DIR) {
  state = process.env.TACK_STATE_DIR;
} else if (process.env.XDG_STATE_HOME) {
  state = path.join(process.env.XDG_STATE_HOME, "tack");
} else {
  state = path.join(process.env.HOME || os.homedir(), ".local", "state", "tack");
}
const STATE = state;
const SOCKET = process.env.TACK_SOCKET || path.join(STATE, "tack.sock");
const DAEMON_LOG = path.join(STATE, "daemon.log");

// Reply::Error classes map to named reasons, never a single catch-all.
const ERROR_REASONS = new Map([
  ["protocol_version", "protocol_version"],
  ["limit", "limit"],
  ["script", "script"],
  ["unknown_tool", "unknown_tool"],
  ["malformed", "daemon_error"],
  ["too_large", "daemon_error"],
  ["unsupported_hook", "daemon_error"],
]);

const REASONS = new Set(DENY_REASONS);
let sequence = 0;
let starting;

// Identity of the socket's filesystem object. dev belongs to it: a fast
// unlink/rebind can reuse the inode and leave mtime in the same millisecond.
function socketIdentity() {
  try {
    const info = fs.statSync(SOCKET);
    return info.dev + ":" + info.ino + ":" + info.mtimeMs;
  } catch {
    return undefined;
  }
}

function nextId() {
  sequence = (sequence + 1) % Number.MAX_SAFE_INTEGER;
  return sequence;
}

// A reason the protocol does not declare degrades to the safe fallback.
function denyName(name) {
  return REASONS.has(name) ? name : "malformed_reply";
}

function errorReason(kind) {
  return ERROR_REASONS.get(kind) || "daemon_error";
}

function daemonBin() {
  return process.env.TACK_DAEMON_BIN || DAEMON_BIN;
}

function startDaemon() {
  if (!starting) {
    starting = new Promise((resolve) => {
      let done = false;
      let timer;
      let poll;
      let child;

      const finish = (ok) => {
        if (done) return;
        done = true;
        clearTimeout(timer);
        clearInterval(poll);
        // A failed or dead start must not poison later calls.
        starting = undefined;
        resolve(ok);
      };

      // A stale socket file can survive a dead daemon. Record its identity so
      // readiness means a fresh bind, not just a path that already exists.
      const stale = socketIdentity();

      const ready = () => {
        if (!fs.existsSync(SOCKET)) return false;
        const current = socketIdentity();
        return current !== undefined &&
          (stale === undefined || current !== stale);
      };

      timer = setTimeout(() => finish(ready()), START_TIMEOUT_MS);

      try {
        // The daemon unlinks a stale socket only after it holds the lock, so
        // a second start here must never remove a live daemon's socket.
        fs.mkdirSync(STATE, { recursive: true });
        const log = fs.openSync(DAEMON_LOG, "a");
        child = spawn(daemonBin(), ["--socket", SOCKET, "--plugin", PLUGIN_DIR], {
          detached: true,
          stdio: ["ignore", log, log],
        });
        child.on("error", () => finish(ready()));
        child.on("exit", () => finish(ready()));
        child.unref();
        fs.closeSync(log);
      } catch {
        finish(false);
        return;
      }

      poll = setInterval(() => {
        if (ready()) finish(true);
      }, POLL_MS);
    });
  }
  return starting;
}

function forward(request) {
  return new Promise((resolve) => {
    let settled = false;
    let active;
    let timer;
    let waitingForStart = false;
    let startedIdentity;
    let restartedOnce = false;

    const stopTimer = () => {
      if (timer === undefined) return;
      clearTimeout(timer);
      timer = undefined;
    };

    const finish = (result) => {
      if (settled) return;
      settled = true;
      stopTimer();
      if (active && !active.destroyed) active.destroy();
      resolve(result);
    };

    const deny = (name) => finish({ ok: false, reason: denyName(name) });

    const connect = () => {
      stopTimer();
      if (settled) return;

      // A fresh socket can be unlinked and rebound after the start attempt
      // resolved. Re-check here, not only in the poll: another change is a
      // stale socket, so restart once at most.
      if (startedIdentity !== undefined && !restartedOnce &&
          socketIdentity() !== startedIdentity) {
        restartedOnce = true;
        startedIdentity = undefined;
        startDaemon().then(() => {
          if (settled) return;
          startedIdentity = socketIdentity();
          connect();
        });
        return;
      }

      const sock = net.connect(SOCKET);
      let abandoned = false;
      let buffer = Buffer.alloc(0);
      active = sock;
      timer = setTimeout(() => deny("timeout"), CALL_TIMEOUT_MS);

      sock.on("connect", () => {
        sock.write(JSON.stringify(request) + "\n");
      });

      sock.on("data", (chunk) => {
        buffer = Buffer.concat([buffer, chunk]);
        // The cap covers the whole buffer, even after the newline arrives.
        if (buffer.length > MAX_LINE) {
          deny("malformed_reply");
          return;
        }
        const newline = buffer.indexOf(0x0a);
        if (newline < 0) return;

        let reply;
        try {
          reply = JSON.parse(buffer.subarray(0, newline).toString("utf8"));
        } catch {
          deny("malformed_reply");
          return;
        }
        if (!reply || typeof reply !== "object" || reply.id !== request.id ||
            !KINDS.has(reply.kind)) {
          deny("malformed_reply");
          return;
        }
        if (reply.version !== PROTOCOL_VERSION) {
          deny("protocol_version");
          return;
        }
        if (reply.kind === "error") {
          deny(errorReason(reply.error));
          return;
        }
        finish({ ok: true, reply });
      });

      sock.on("close", () => {
        if (!abandoned) deny("socket_closed");
      });

      sock.on("error", (error) => {
        const code = error && error.code;
        const stale = code === "ENOENT" || code === "ECONNREFUSED";
        if (stale && !waitingForStart && process.env.TACK_NO_START !== "1") {
          waitingForStart = true;
          abandoned = true;
          stopTimer();
          startDaemon().then(() => {
            if (settled) return;
            // Readiness can lag a competing daemon's bind. A real connect is
            // the only proof of reachability; waitingForStart bounds this to
            // one retry, and this connect has not written a request.
            startedIdentity = socketIdentity();
            connect();
          });
          return;
        }
        deny(code === "ENOENT" ? "socket_missing" : "socket_closed");
      });
    };

    connect();
  });
}

async function before(event) {
  const input = event.input || (event.input = {});
  const tool = event.tool || input.tool || "";
  const call = {
    tool,
    name: event.name || input.name || tool,
    input,
    session_id: event.sessionID || event.session_id || undefined,
  };
  const result = await forward({
    id: nextId(),
    kind: "hook",
    hook: "toolBefore",
    version: PROTOCOL_VERSION,
    call,
  });
  if (!result.ok) throw new Error("tack: " + result.reason);
  if (result.reply.kind !== "hook") {
    throw new Error("tack: " + denyName("malformed_reply"));
  }

  const outcome = result.reply.outcome;
  if (!outcome || typeof outcome !== "object") {
    throw new Error("tack: " + denyName("malformed_reply"));
  }
  if (outcome.kind === "deny") {
    throw new Error("tack: " + (outcome.reason || "denied"));
  }
  if (outcome.kind === "rewrite") {
    const rewritten = outcome.input;
    const plain = rewritten !== null && typeof rewritten === "object" &&
      !Array.isArray(rewritten);
    if (!plain) throw new Error("tack: " + denyName("malformed_reply"));
    event.input = rewritten;
    return;
  }
  if (outcome.kind !== "allow") {
    throw new Error("tack: " + denyName("malformed_reply"));
  }
}

function setup(ctx) {
  const registrations = [ctx.tool.hook("execute.before", before)];

  for (const definition of MANIFEST.tools) {
    registrations.push(
      ctx.tool.transform((editor) =>
        editor.add({
          name: definition.name,
          description: definition.description,
          input: definition.input,
          options: { codemode: false },
          async execute(args) {
            const result = await forward({
              id: nextId(),
              kind: "tool",
              name: definition.name,
              input: args,
              version: PROTOCOL_VERSION,
            });
            if (!result.ok) throw new Error("tack: " + result.reason);
            if (result.reply.kind !== "tool") {
              throw new Error("tack: " + denyName("malformed_reply"));
            }
            return {
              content: (result.reply.content || []).map((item) => ({
                type: "text",
                text: item.text,
              })),
            };
          },
        }),
      ),
    );
  }

  return async () => {
    for (const registration of registrations) {
      if (registration && typeof registration.dispose === "function") {
        await registration.dispose();
      }
    }
  };
}

module.exports = { id: "tack." + MANIFEST.name, setup };
